const XLSX = require('xlsx');
const docx = require('docx');
const fs = require('fs');

// Read the Excel data
const wb = XLSX.readFile('data/product_inventory.xlsx');
const ws = wb.Sheets['Products'];
const products = XLSX.utils.sheet_to_json(ws);

// Compute summary stats
const totalProducts = products.length;
const categories = {};
products.forEach(p => {
  const cat = p['Category'];
  categories[cat] = (categories[cat] || 0) + 1;
});
const prices = products.map(p => p['Price']);
const minPrice = Math.min(...prices);
const maxPrice = Math.max(...prices);
const avgPrice = (prices.reduce((a, b) => a + b, 0) / prices.length).toFixed(2);
const allInStock = products.every(p => p['In Stock'] === 'Yes');

// Build the Word document
const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, HeadingLevel } = docx;

const borderNone = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
const noBorders = { top: borderNone, bottom: borderNone, left: borderNone, right: borderNone };

// Category breakdown paragraphs
const categoryLines = Object.entries(categories)
  .sort((a, b) => b[1] - a[1])
  .map(([cat, count]) => new Paragraph({
    bullet: { level: 0 },
    children: [
      new TextRun({ text: `${cat}`, bold: true }),
      new TextRun({ text: `: ${count} product${count > 1 ? 's' : ''}` }),
    ],
  }));

// Product table header
const headerRow = new TableRow({
  tableHeader: true,
  children: ['Product ID', 'Name', 'Category', 'Price', 'In Stock'].map(label =>
    new TableCell({
      children: [new Paragraph({ children: [new TextRun({ text: label, bold: true, font: 'Calibri', size: 20, color: 'FFFFFF' })] })],
      shading: { fill: '2E75B6' },
      width: { size: 20, type: WidthType.PERCENTAGE },
    })
  ),
});

// Product table data rows
const dataRows = products.map((p, i) =>
  new TableRow({
    children: [p['Product ID'], p['Name'], p['Category'], `$${p['Price']}`, p['In Stock']].map(val =>
      new TableCell({
        children: [new Paragraph({ children: [new TextRun({ text: String(val), font: 'Calibri', size: 20 })] })],
        shading: { fill: i % 2 === 0 ? 'F2F2F2' : 'FFFFFF' },
        width: { size: 20, type: WidthType.PERCENTAGE },
      })
    ),
  })
);

const doc = new Document({
  sections: [{
    properties: {},
    children: [
      // Title
      new Paragraph({
        heading: HeadingLevel.HEADING_1,
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: 'Product Inventory Summary', bold: true, font: 'Calibri', size: 36, color: '2E75B6' })],
      }),

      // Date
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 300 },
        children: [new TextRun({ text: `Generated on ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}`, italics: true, font: 'Calibri', size: 20, color: '666666' })],
      }),

      // Overview heading
      new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 200 }, children: [new TextRun({ text: 'Overview', bold: true, font: 'Calibri', size: 28 })] }),

      new Paragraph({
        spacing: { after: 200 },
        children: [
          new TextRun({ text: `This inventory contains `, font: 'Calibri', size: 22 }),
          new TextRun({ text: `${totalProducts} products`, bold: true, font: 'Calibri', size: 22 }),
          new TextRun({ text: ` spanning `, font: 'Calibri', size: 22 }),
          new TextRun({ text: `${Object.keys(categories).length} categories`, bold: true, font: 'Calibri', size: 22 }),
          new TextRun({ text: `. Prices range from `, font: 'Calibri', size: 22 }),
          new TextRun({ text: `$${minPrice}`, bold: true, font: 'Calibri', size: 22 }),
          new TextRun({ text: ` to `, font: 'Calibri', size: 22 }),
          new TextRun({ text: `$${maxPrice}`, bold: true, font: 'Calibri', size: 22 }),
          new TextRun({ text: `, with an average price of `, font: 'Calibri', size: 22 }),
          new TextRun({ text: `$${avgPrice}`, bold: true, font: 'Calibri', size: 22 }),
          new TextRun({ text: `.`, font: 'Calibri', size: 22 }),
        ],
      }),

      // Stock status
      new Paragraph({
        spacing: { after: 200 },
        children: [
          new TextRun({
            text: allInStock
              ? 'All 20 listed items are marked In Stock as Yes — no items are currently out of stock.'
              : 'Some items are currently out of stock.',
            font: 'Calibri', size: 22, bold: true, color: allInStock ? '2E7D32' : 'C62828',
          }),
        ],
      }),

      // Category breakdown heading
      new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 200 }, children: [new TextRun({ text: 'Category Breakdown', bold: true, font: 'Calibri', size: 28 })] }),

      ...categoryLines,

      // Full product listing heading
      new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 400, after: 200 }, children: [new TextRun({ text: 'Full Product Listing', bold: true, font: 'Calibri', size: 28 })] }),

      // Table
      new Table({
        rows: [headerRow, ...dataRows],
        width: { size: 100, type: WidthType.PERCENTAGE },
      }),
    ],
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('data/inventory_summary.docx', buffer);
  console.log('✅ Saved to data/inventory_summary.docx');
});
